export const DEFAULT_BUDGET_FILE = join(THIS_DIR, "..", "..", "temp", "compact_budget.json");
let budgetFile = DEFAULT_BUDGET_FILE;
// Test hook (the setDbPath pattern — the probe/smokes steer the read at
